record Empty;
record class Point(long X, long Y);
record Pair(Point Left, Point Right);
void Main() {
 var a = new Empty(); var b = a with {}; Print(a == b); Print(a.GetHashCode() == b.GetHashCode());
 var p = new Pair(new Point(1, 2), new Point(3, 4));
 var q = p with { Left = p.Left with { X = 10 } };
 Print(p.Left.X); Print(q.Left.X); Print(p.Right == q.Right); Print(p != q);
 var yes = true; var chosen = yes ? p with {} : q with {}; Print(chosen == p);
 Print((p with {} == p) && (p == p with {}));
}
